pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Penalty for creating "dead space": residuals that are too small to fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead optimization: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Global state adjustment: If we have many bins open, be more aggressive 
    // about filling the current ones (Best Fit).
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Dynamic horizon: As we approach the end of the stream, prioritize 
    // filling existing bins to reduce the final bin count.
    if progress > 0.8 {
        score -= (1.0 - progress) * 100.0;
    }

    // 6. Handle the "New Bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (we are forced)
        // or if we have very few open bins and want to keep them somewhat empty for future flexibility.
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Apply a heavy penalty to opening new bins unless necessary
            score = 50.0 + (mean_residual * 0.5);
        }
    }

    // 7. Last chance heuristic: If this is the only bin that fits the item, 
    // prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (leftover space too small for any likely future item)
    // We treat 10 as the lower bound of item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Dynamic penalty for opening new bins
    // As the stream progresses, we become more conservative about opening new bins
    if is_new_bin {
        score += 25.0 + (35.0 * progress);

        // If we have other options, discourage opening a new bin unless it's very efficient
        if fitting_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Lookahead coupling: If the next item fits into the current post_residual, 
    // reward this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Balancing: Favor bins that align with the global mean residual to avoid 
    // creating extreme outliers in bin fullness.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev_from_mean;

    // Penalize high open_bins_count to encourage consolidation early in the stream
    if !is_new_bin {
        score += (open_bins_count as f64) * 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin (bin_residual == bin_capacity) using a dynamic threshold 
    // that increases as the stream progresses, forcing tighter packing later on.
    let new_bin_penalty = 25.0 + (progress * 50.0);

    let base_score = if bin_residual == bin_capacity {
        new_bin_penalty
    } else {
        post
    };

    // Non-linear coupling: penalize small residuals that are unlikely to accommodate 
    // the next item, balanced by the mean residual of the current state.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 1.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Reward bins that bring the bin towards the global mean residual (Best-Fit-like behavior)
    // while penalizing bins that are too empty early in the stream.
    let dispersion = (post - mean_residual).abs() * 0.2;

    // If only one bin fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    let scarcity_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -15.0
    } else {
        0.0
    };

    base_score + lookahead_penalty + dispersion + scarcity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin.
    // Lower residual is generally better (Best-Fit principle).
    let mut score = post_res;

    // Penalty for creating a "sliver" (fragmentation):
    // If post_residual is small (1-15), it's often unusable for future items.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_res) * 2.5;
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // reward this bin to keep the packing dense.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic adjustment based on stream progression:
    // As we approach the end of the stream, we become increasingly aggressive 
    // about filling bins to avoid leaving too many partially full bins open.
    let end_game_pressure = progress * 50.0;
    score += (mean_residual - post_res) * end_game_pressure;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with the number of bins already open and the phase of the stream.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64 * 2.0) + (progress * 40.0);
    }

    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // prioritize it to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: Lower post_residual is generally better (less waste).
    // 2. Penalty for opening new bins: Only open if forced or if current fit is abysmal.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Penalize opening a new bin unless the current fit options are poor (e.g., leaving < 10 space)
        score = 45.0 + (mean_residual * 0.5);
    }

    // 3. Lookahead Logic: If next_item_size fits in the post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward perfect matches for the lookahead
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 4. Dead space avoidance: Penalize post_residual ranges that are too small to fit typical items (10-20)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 5. Fitting constraint: If this is the only fitting bin, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Global density awareness: If we are late in the stream, be more aggressive about filling bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize dead space (< 10) 
    // that is too small for any future item, while accounting for lookahead.

    let mut score = post_residual as f64;

    // 1. Penalize "useless" gaps: If a gap is between 1 and 9, it's likely unusable 
    // given the item size range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead awareness: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small for the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 3. Open bins pressure: As we progress, if we have many open bins, 
    // be more aggressive about filling existing ones to avoid fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress);

    // 4. New bin thresholding:
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    // Penalize opening a new bin unless the existing fitting bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage Best-Fit.
        score += 45.0;

        // If we have very few open bins, opening a new one is cheaper than 
        // if we are already dealing with many fragmented bins.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. Tie-breaking: If we are forced to pick between multiple bins, 
    // prioritize the one that leaves the bin closest to being full (lower post_residual).
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but cannot fit the next item.
    // We want to avoid creating "dead zones" that are smaller than the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // 2. Best-Fit/First-Fit coupling: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 3. New Bin Thresholding: Only open a new bin if the current fit is extremely poor (large residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin unless the remaining space in existing bins is highly fragmented.
            score = 35.0 + (mean_residual * 0.5);
        }
    }

    // 4. Modulo/Fractional Alignment: Reward placements that leave a residual which is a multiple of 
    // common item sizes (e.g., 20, 25, 50) to increase the likelihood of future perfect fits.
    if post_residual > 0 {
        let remainder = post_residual % 20;
        if remainder == 0 {
            score -= 10.0;
        } else {
            score += (20 - remainder) as f64 * 0.2;
        }
    }

    // 5. Progression adjustment: As the stream nears the end, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
